void test_dilithium_api() {
    uint8_t out[32];

    print_string("\n=== Test via Symmetric.h API (Dilithium) ===\n");

    /* ----------------------------------------------------------------
     * TEST 1: "abcd" (4 bytes)
     * ---------------------------------------------------------------- */
    print_string("\n[TEST] dilithium_shake256('abcd')...\n");
    
    dilithium_shake256(out, 32, (const uint8_t*)"abcd", 4);
    
    print_string(" Expect: ");
    print_hex(golden_abcd_dil, 32, 0);
    print_string(" Got:    ");
    print_hex(out, 32, 0);

    if (memcmp(out, golden_abcd_dil, 32) == 0) {
        print_string(" RESULT: PASS\n");
    } else {
        print_string(" RESULT: FAIL\n");
    }

    /* ----------------------------------------------------------------
     * TEST 2: "abc" (3 bytes)
     * Unaligned. Dilithium typically ignores partial words (3 >> 2 = 0).
     * This confirms if Dilithium API fails for unaligned data.
     * ---------------------------------------------------------------- */
    print_string("\n[TEST] dilithium_shake256('abcdefgh')....\n");
    
    dilithium_shake256(out, 32, (const uint8_t*)"abcdefgh", 8);
    
    print_string(" Expect: ");
    print_hex(golden_abcdefgh_dil, 32, 0);
    print_string(" Got:    ");
    print_hex(out, 32, 0);

    if (memcmp(out, golden_abcdefgh_dil, 32) == 0) {
        print_string(" RESULT: PASS\n");
    } else {
        print_string(" RESULT: FAIL (Expected behavior for Dilithium unaligned)\n");
    }
}

void test_unaligned_injection() {
    shake256_context sc;
    uint8_t out[32];
    /* "12345" aligned */
    uint8_t buffer_aligned[] = "12345678"; 
    /* "12345" unaligned (offset by 1) */
    uint8_t *buffer_unaligned = buffer_aligned + 1; 

    print_string("\n=== Test: Unaligned Injection ===\n");

    /* 1. Reference: Hash "2345" (aligned logic) */
    shake256_init(&sc);
    shake256_inject(&sc, "2345", 4);
    shake256_flip(&sc);
    shake256_extract(&sc, out, 32);
    uint32_t ref_hash = (out[0]<<24)|(out[1]<<16)|(out[2]<<8)|out[3];
    print_string("Reference Hash ('2345'): "); print_u32(ref_hash); print_string("\n");

    /* 2. Test: Hash "2345" (unaligned pointer) */
    shake256_init(&sc);
    /* buffer_unaligned points to '2', but address is Odd */
    shake256_inject(&sc, buffer_unaligned, 4); 
    shake256_flip(&sc);
    shake256_extract(&sc, out, 32);
    uint32_t test_hash = (out[0]<<24)|(out[1]<<16)|(out[2]<<8)|out[3];
    print_string("Unaligned Hash ('2345'): "); print_u32(test_hash); print_string("\n");

    if (ref_hash == test_hash) {
        print_string("RESULT: PASS (Wrapper handles unaligned safe)\n");
    } else {
        print_string("RESULT: FAIL (DMA/Race condition detected)\n");
    }
}


