void test_long_squeeze() {
    shake256_context sc;
    uint8_t out[160];
    int i;
    int mismatches = 0;

    print_string("\n=== Test: Long Squeeze (160 Bytes) ===\n");
    print_string("Checking for boundaries at 128 or 136 bytes...\n");

    shake256_init(&sc);
    shake256_inject(&sc, "abc", 3);
    shake256_flip(&sc);
    
    /* Request 160 bytes in one go */
    shake256_extract(&sc, out, 160);

    for (i = 0; i < 160; i++) {
        if (out[i] != golden_long_squeeze[i]) {
            if (mismatches == 0) {
                /* Print the first failure only */
                print_string("FAIL at Index: ");
                print_u32(i);
                print_string("\n");
                print_string("  Expected: "); print_u32(golden_long_squeeze[i]);
                print_string("\n  Got:      "); print_u32(out[i]);
                print_string("\n");
            }
            mismatches++;
        }
    }

    if (mismatches == 0) {
        print_string("RESULT: PASS (Long squeeze safe)\n");
    } else {
        print_string("RESULT: FAIL (Total mismatches: ");
        print_u32(mismatches);
        print_string(")\n");
    }
}

void debug_squeeze_words() {
    shake256_context sc;
    uint32_t word;
    int i;
    
    /* Expected first 9 words for "abc" */
    uint32_t expected[] = {
        0x60663348, // Word 0
        0x77a86013, // Word 1
        0x0863681c, // Word 2
        0x4d11c40c, // Word 3
        0x3045b48d, // Word 4
        0xeee1f1f8, // Word 5
        0x37ea944f, // Word 6
        0x39578be7, // Word 7 (Last of 32-byte block)
        0xef6b7da8  // Word 8 (First of NEXT block - THE FAIL POINT)
    };

    print_string("\n=== Squeeze Micro-Debug ===\n");
    
    shake256_init(&sc);
    shake256_inject(&sc, "abc", 3);
    shake256_flip(&sc);
    
    for(i=0; i<9; i++) {
        keccak_squeeze(&word, NULL, 1); // Ask for 1 word at a time
        
        print_string("Word "); print_u32(i); 
        print_string(": Got "); print_u32(word);
        
        if (word == expected[i]) {
            print_string(" [OK]\n");
        } else {
            print_string(" [FAIL] Exp "); print_u32(expected[i]); print_string("\n");
        }
    }
}
void debug_squeeze_repeat() {
    shake256_context sc;
    uint32_t buf1[8];
    uint32_t buf2[8];
    int i;
    
    print_string("\n=== Debug: Squeeze Repeat Analysis ===\n");
    
    shake256_init(&sc);
    shake256_inject(&sc, "abc", 3);
    shake256_flip(&sc);
    
    /* Request first 32 bytes */
    keccak_squeeze(buf1, NULL, 8);
    
    /* Request next 32 bytes (supposedly) */
    keccak_squeeze(buf2, NULL, 8);
    
    print_string("Chunk 1 (Words 0-3): ");
    print_u32(buf1[0]); print_string(" "); print_u32(buf1[1]); print_string(" ");
    print_u32(buf1[2]); print_string(" "); print_u32(buf1[3]); print_string("\n");

    print_string("Chunk 2 (Words 0-3): ");
    print_u32(buf2[0]); print_string(" "); print_u32(buf2[1]); print_string(" ");
    print_u32(buf2[2]); print_string(" "); print_u32(buf2[3]); print_string("\n");

    if (buf1[0] == buf2[0] && buf1[1] == buf2[1]) {
        print_string("CONCLUSION: Hardware resets index to 0 every call!\n");
        print_string("Status: We are reading the same 32 bytes over and over.\n");
    } else {
        print_string("CONCLUSION: Hardware returns different data (Garbage or Next).\n");
    }
}
